def service_card(x):
 icon,title,desc,handle,cat=x
 href='/products/'+handle if handle=='interview-prep' else '/collections/packages'
 label='Explore this service' if handle=='interview-prep' else 'See the plans'
 return f'<article class="service-card" data-category="{cat}"><span class="service-icon" aria-hidden="true">{icon}</span><h3>{title}</h3><p>{desc}</p><a href="{href}">{label} <span aria-hidden="true">↗</span></a></article>'
servicebody='<section class="section" id="services"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Support that meets you where you are</span><h2>A little direction.<br>A lot of possibility.</h2></div><p>Get help with one specific challenge or a plan that brings it all together. Your goals set the direction.</p></div><div class="service-grid">'+''.join(map(service_card,services))+'</div><div class="service-more"><a href="/collections/packages">Technical study sessions ↗</a><a href="/collections/packages">Personalized cheat sheets ↗</a><a href="/collections/packages">Interview guides ↗</a></div></div></section>'
