# Static preview uses the same section markup, stylesheet, and scripts as the theme.
def render(text):
 for key,value in [('heading','The only application you will ever'),('accent','fill out.'),('description','Scroll. Plug in each step. Then submit with Buy Now.')]: text=text.replace('{{ section.settings.'+key+' | escape }}',value)
 text=re.sub(r"{% comment %}.*?{% endcomment %}",'',text,flags=re.S)
 text=re.sub(r"{% if settings\.show_draft_notes %}(.*?){% endif %}",r'\1',text,flags=re.S)
 for k,v in PRICES.items(): text=text.replace('{{ settings.price_'+k+' }}',str(v))
 for k,v in HANDLES.items(): text=text.replace('{{ settings.handle_'+k+' }}',v)
 text=re.sub(r"{% render 'jp-buy-now', handle: settings\.handle_(\w+), cls: '([\w-]*)' %}",lambda m:'<a class="btn '+m[2]+'" href="/products/'+HANDLES[m[1]]+'">Buy Now</a>',text)
 text=text.replace("{% render 'jp-book-prep' %}",'<a class="btn outline placeholder" href="#packages" aria-disabled="true">Book Interview Prep [CONFIRM booking app link]</a>')
 text=text.replace("{% render 'jp-start-setup' %}",'<a class="btn" href="'+FORM+'" target="_blank" rel="noopener">Start Your Setup</a>')
 text=re.sub(r"{{ '([^']+)' \| asset_url }}",r'/assets/\1',text)
 text=text.replace('{{ settings.google_form_url | escape }}',FORM).replace('{{ "now" | date: "%Y" }}','2026')
 text=re.sub(r'{% for policy.*?{% endfor %}','',text,flags=re.S)
 return text
